def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    strong_prev = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                if bid >= 80:
                    strong_prev.append(bid)

    if not alive:
        return max(0.0, min(budget, 18.0))

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    bob_bid = None
    cindy_bid = None
    for agent_id, opp in alive:
        prev = opp.get('previous_trace', {})
        if agent_id == 'Bob' and prev.get('bid') is not None:
            bob_bid = prev.get('bid')
        if agent_id == 'Cindy' and prev.get('bid') is not None:
            cindy_bid = prev.get('bid')

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 3
    elif hp <= 6:
        urgency += 2
    else:
        urgency += 1

    if no_water >= 2:
        urgency += 4
    elif no_water >= 1:
        urgency += 2

    if supply <= 17:
        urgency += 3
    elif supply <= 19:
        urgency += 2
    elif supply <= 21:
        urgency += 1

    if budget < 80:
        urgency += 1

    if urgency >= 8:
        target = 0.96 * DAILY_SALARY
        if bob_bid is not None:
            target = max(target, bob_bid + 2.0)
        return max(0.0, min(budget, target))

    if urgency >= 6:
        target = 0.78 * DAILY_SALARY + scarcity * 10.0
        if bob_bid is not None and supply <= 19:
            target = max(target, bob_bid + 1.5)
        return max(0.0, min(budget, target))

    if urgency >= 4:
        base = 0.48 * DAILY_SALARY + scarcity * 8.0
        if bob_bid is not None and bob_bid < 90 and supply <= 18:
            base = max(base, bob_bid + 1.0)
        return max(0.0, min(budget, base))

    if cindy_bid is not None and cindy_bid >= 120 and supply >= 20:
        return max(0.0, min(budget, 12.0))

    if bob_bid is not None and bob_bid >= 100 and supply >= 19 and hp >= 6:
        return max(0.0, min(budget, 15.0))

    if strong_prev and supply <= 18:
        target = min(strong_prev) + 1.0
        target = max(target, 32.0)
        target = min(target, 62.0)
        return max(0.0, min(budget, target))

    return max(0.0, min(budget, 22.0 + scarcity * 10.0))

