def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    if not alive:
        return max(0.0, min(float(my_status.get('budget', 0.0)), DAILY_SALARY * 0.4))

    # Read yesterday bids to infer aggressiveness.
    prev_bids = []
    for oid, o in alive:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # If everyone bid low yesterday, we can safely bid a bit higher than the median.
    if prev_bids:
        sorted_b = sorted(prev_bids)
        n = len(sorted_b)
        median_bid = sorted_b[n // 2] if n % 2 == 1 else (sorted_b[n // 2 - 1] + sorted_b[n // 2]) / 2.0
        max_prev = max(sorted_b)
    else:
        median_bid = DAILY_SALARY * 0.5
        max_prev = DAILY_SALARY * 0.9

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Supply tightness: if supply is near the minimum, competition is higher.
    # With supply in [15,25], compute a rough pressure factor.
    # Use int() for any indexing (none used) and keep arithmetic float-safe.
    tight = (25.0 - supply) / 10.0  # 0 when supply=25, 1 when supply=15
    tight = max(0.0, min(1.0, float(tight)))

    # Base bid: slightly above median to beat low bidders, but cap to avoid draining budget.
    # Increase if my HP is low or I've already missed water days.
    hp_pressure = 0.0
    if hp <= 2.0:
        hp_pressure = 1.0
    elif hp <= 4.0:
        hp_pressure = 0.6
    elif hp <= 6.0:
        hp_pressure = 0.3

    missed_pressure = 0.0
    if no_water_days >= 2:
        missed_pressure = 1.0
    elif no_water_days == 1:
        missed_pressure = 0.5

    pressure = 0.25 + 0.5 * tight + 0.25 * hp_pressure + 0.25 * missed_pressure
    # Convert pressure into a target multiplier of DAILY_SALARY.
    target = DAILY_SALARY * (0.35 + 0.55 * pressure)

    # Ensure we are competitive vs likely low-bid cluster.
    # If median is far below target, still bid near target; if median is high, bid a bit above it.
    bid = max(target, median_bid + 2.0)

    # If someone ever bid extremely high yesterday, avoid overreacting unless my HP is critical.
    if hp > 3.0 and max_prev > DAILY_SALARY * 1.4:
        bid = min(bid, DAILY_SALARY * 1.05)

    # Final safety caps.
    bid = max(0.0, min(bid, budget, DAILY_SALARY * 1.25))

    # If budget is too low, bid what we can.
    if budget <= 1.0:
        return max(0.0, budget)

    return float(bid)
